public int[] componentSizes(int totalNodes, int[][] edges) {
    List<List<Integer>> adj = new ArrayList<>();
    for (int i = 0; i <= totalNodes; i++) adj.add(new ArrayList<>());
    boolean[] inEdge = new boolean[totalNodes + 1];
    for (int[] e : edges) {
        adj.get(e[0]).add(e[1]);
        adj.get(e[1]).add(e[0]);
        inEdge[e[0]] = true;
        inEdge[e[1]] = true;
    }
    boolean[] visited = new boolean[totalNodes + 1];
    int smallest = Integer.MAX_VALUE, largest = 0;
    for (int start = 1; start <= totalNodes; start++) {
        if (!inEdge[start] || visited[start]) continue;
        int size = 0;
        Deque<Integer> stack = new ArrayDeque<>();
        stack.push(start);
        visited[start] = true;
        while (!stack.isEmpty()) {            // iterative DFS, no stack overflow
            int u = stack.pop();
            size++;
            for (int v : adj.get(u)) {
                if (!visited[v]) {
                    visited[v] = true;
                    stack.push(v);
                }
            }
        }
        if (size >= 2) {
            smallest = Math.min(smallest, size);
            largest = Math.max(largest, size);
        }
    }
    return new int[]{smallest, largest};
}

