def component_sizes(self, total_nodes: int, edges: list[list[int]]) -> tuple[int, int]:
    adj: list[list[int]] = [[] for _ in range(total_nodes + 1)]
    in_edge = [False] * (total_nodes + 1)
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)
        in_edge[u] = in_edge[v] = True
    visited = [False] * (total_nodes + 1)
    smallest, largest = float('inf'), 0
    for start in range(1, total_nodes + 1):
        if not in_edge[start] or visited[start]:
            continue
        size = 0
        stack = [start]                       # iterative DFS, no recursion limit
        visited[start] = True
        while stack:
            u = stack.pop()
            size += 1
            for v in adj[u]:
                if not visited[v]:
                    visited[v] = True
                    stack.append(v)
        if size >= 2:
            smallest = min(smallest, size)
            largest = max(largest, size)
    return smallest, largest

