public int[] componentSizes(int totalNodes, int[][] edges) {
    int[] parent = new int[totalNodes + 1];
    int[] rank = new int[totalNodes + 1];
    int[] size = new int[totalNodes + 1];
    boolean[] inEdge = new boolean[totalNodes + 1];
    for (int i = 1; i <= totalNodes; i++) {
        parent[i] = i;
        size[i] = 1;
    }
    for (int[] e : edges) {
        inEdge[e[0]] = inEdge[e[1]] = true;
        union(parent, rank, size, e[0], e[1]);
    }
    int smallest = Integer.MAX_VALUE, largest = 0;
    for (int i = 1; i <= totalNodes; i++) {
        if (inEdge[i] && find(parent, i) == i && size[i] >= 2) {
            smallest = Math.min(smallest, size[i]);
            largest = Math.max(largest, size[i]);
        }
    }
    return new int[]{smallest, largest};
}

private int find(int[] parent, int x) {
    while (parent[x] != x) {
        parent[x] = parent[parent[x]];           // path halving, iterative
        x = parent[x];
    }
    return x;
}

private void union(int[] parent, int[] rank, int[] size, int a, int b) {
    int ra = find(parent, a), rb = find(parent, b);
    if (ra == rb) return;
    if (rank[ra] < rank[rb]) { int t = ra; ra = rb; rb = t; }
    parent[rb] = ra;
    size[ra] += size[rb];                        // size lives on the root
    if (rank[ra] == rank[rb]) rank[ra]++;
}

