def component_sizes(self, total_nodes: int, edges: list[list[int]]) -> tuple[int, int]:
    parent = list(range(total_nodes + 1))
    rank = [0] * (total_nodes + 1)
    size = [1] * (total_nodes + 1)
    in_edge = [False] * (total_nodes + 1)

    def find(x: int) -> int:
        while parent[x] != x:
            parent[x] = parent[parent[x]]        # path halving, iterative
            x = parent[x]
        return x

    def union(a: int, b: int) -> None:
        ra, rb = find(a), find(b)
        if ra == rb:
            return
        if rank[ra] < rank[rb]:
            ra, rb = rb, ra
        parent[rb] = ra
        size[ra] += size[rb]                     # size lives on the root
        if rank[ra] == rank[rb]:
            rank[ra] += 1

    for u, v in edges:
        in_edge[u] = in_edge[v] = True
        union(u, v)

    smallest, largest = float('inf'), 0
    for i in range(1, total_nodes + 1):
        if in_edge[i] and find(i) == i and size[i] >= 2:
            smallest = min(smallest, size[i])
            largest = max(largest, size[i])
    return smallest, largest

